#!/usr/bin/env bash
# One-click installer: downloads the latest Tracker Calibration from GitHub and installs it.
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/fbt-calibrator/main/get.sh | bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
set -euo pipefail
REPO="lokinyauv-create/fbt-calibrator"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
TAG="$(curl -fsSL "https://api.github.com/repos/$REPO/releases/latest" | grep -o '"tag_name": *"[^"]*"' | cut -d'"' -f4 || true)"
REF="${TAG:+refs/tags/$TAG}"; REF="${REF:-refs/heads/main}"
echo "Downloading Tracker Calibration ${TAG:-main}… / Завантажую Калібрування трекерів…"
curl -fsSL "https://codeload.github.com/$REPO/tar.gz/$REF" | tar -xz -C "$T" --strip-components=1
bash "$T/install.sh"
